CREATE OR REPLACE FUNCTION public.eco_public_contributors() RETURNS TABLE(display_id text,name text,profile_path text,approved bigint,cleaning bigint,plastic_kg numeric,saplings bigint,photos bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.display_id,p.name,p.profile_path,count(c.activity_id),count(c.activity_id) FILTER(WHERE c.category IN ('plastic','cleaning','dustbins')),sum(c.plastic_kg),sum(c.saplings)::bigint,sum(c.photo_count)::bigint FROM eco_participants p JOIN eco_contribution_snapshots c ON c.participant_id=p.id AND c.status='approved' WHERE p.public_consent AND NOT p.hidden AND p.removal_requested_at IS NULL GROUP BY p.id ORDER BY count(c.activity_id) DESC,p.display_id LIMIT 100 $$; REVOKE ALL ON FUNCTION public.eco_public_contributors() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.eco_public_contributors() TO anon,authenticated; CREATE OR REPLACE FUNCTION public.eco_public_recent() RETURNS TABLE(id uuid,category text,activity_date date,name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT c.activity_id,c.category,c.activity_date,p.name FROM eco_contribution_snapshots c JOIN eco_participants p ON p.id=c.participant_id WHERE c.status='approved' AND p.public_consent AND NOT p.hidden AND p.removal_requested_at IS NULL ORDER BY c.activity_date DESC,c.activity_id LIMIT 12 $$; REVOKE ALL ON FUNCTION public.eco_public_recent() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.eco_public_recent() TO anon,authenticated; CREATE POLICY eco_consented_profile_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='eco-staging' AND EXISTS(SELECT 1 FROM public.eco_public_contributors() p WHERE p.profile_path=name));